import {planningWarnings,periodLoad} from './planning-insights.js';
import {temporalPlan,bindTimeTips,bindInsertionHints,clearInsertionHints} from './timeline.js';
import {shopfloorView,bindShopfloor} from './shopfloor.js';
import {statisticsView,bindStatistics} from './statistics.js';
const $ = (s, root=document) => root.querySelector(s);
const app=$('#app'), modal=$('#modal');
let showCompleted=false,dragTaskId=null,warningSignature='',planZoom=[.65,1,1.5].includes(Number(localStorage.getItem('aloven-plan-zoom')))?Number(localStorage.getItem('aloven-plan-zoom')):1;
let planDays=localStorage.getItem('aloven-plan-view')==='five'?5:1;
let state, view=location.pathname==='/bordo-macchina'?'shopfloor':'planning', search='', machineFilter='', statusFilter='', dateStart=localDate(), calendarMonth=localDate().slice(0,7), calendarScope='global', dragging=false;
const labels={unplanned:'Da assegnare',planned:'Pianificata',in_progress:'In corso',completed:'Completata',cancelled:'Annullata'};
const days=['Domenica','Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',list:'M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1',machine:'M4 5h16v12H4z M8 21v-4M16 21v-4M8 9h3M15 9h1M8 13h8',calendar:'M4 5h16v16H4z M4 10h16M8 3v4M16 3v4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9',tag:'M3 3h8l10 10-8 8L3 11zM7 7h.01',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',logout:'M9 3H4v18h5M9 12h12M16 7l5 5-5 5',clock:'M12 8v4l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',lock:'M5 10h14v11H5zM8 10V7a4 4 0 0 1 8 0v3'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.grid).split(/(?=M)/).map(d=>`<path d="${d}"/>`).join('')}</svg>`;};
function localDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function addDays(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function fmt(value){if(!value)return 'Non pianificata';return new Intl.DateTimeFormat('it-IT',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'UTC'}).format(new Date(value+'Z'));}
function mins(n){return n<60?`${n} min`:`${Math.floor(n/60)} h${n%60?' '+n%60+' min':''}`;}
function machine(id){return state.machines.find(m=>m.id===id);}
function type(id){return state.types.find(t=>t.id===id);}
function badge(status){return `<span class="badge ${status}">${status==='in_progress'?'<i></i>':''}${labels[status]}</span>`;}
function options(items,value,empty){return `${empty?`<option value="">${empty}</option>`:''}${items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('')}`;}
function toast(message,error=false){if(error&&modal.open){const box=$('.dialog-error',modal);if(box){box.hidden=false;box.textContent=message;}}const t=$('#toast');t.textContent=message;t.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',6000);}
async function api(url,data){const r=await fetch('/api/'+url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-Aloven-Request':'1'}:{},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok){if(r.status===401&&state){modal.close();state=null;await boot();}throw new Error(result.error||'Operazione non riuscita.');}return result;}
function openDialog(html,handler){modal.onclick=modal.oninput=modal.onchange=modal.onkeydown=null;modal.innerHTML=html;modal.firstElementChild?.insertAdjacentHTML('afterend','<div class="dialog-error" role="alert" hidden></div>');modal.showModal();$('[data-close]',modal)?.addEventListener('click',()=>modal.close());if(handler)$('form',modal)?.addEventListener('submit',async e=>{e.preventDefault();const b=$('[type=submit]',modal);b.disabled=true;try{await handler(new FormData(e.target));}catch(err){toast(err.message,true);}finally{if(b.isConnected)b.disabled=false;}});}
function dialogHeader(title,subtitle=''){return `<div class="dialog-heading"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button type="button" class="icon-button" data-close aria-label="Chiudi">×</button></div>`;}
function dialogFooter(label='Salva'){return `<div class="dialog-footer"><button type="button" class="button secondary" data-close-bottom>Annulla</button><button class="button primary" type="submit">${label}</button></div>`;}
modal.addEventListener('click',e=>{if(e.target.closest('[data-close-bottom]'))modal.close();});
async function reload(){state=await api('state');render();}
async function mutate(action,forceConfirm=false){
  const preview=await api('preview',{revision:state.revision,action});
  const needsConfirm=forceConfirm||preview.changes.some(x=>x.oldStart);
  const commit=async()=>{await api('commit',{token:preview.token});modal.close();await reload();toast('Modifiche salvate.');};
  if(!needsConfirm){await commit();return;}
  modal.close();
  openDialog(`${dialogHeader('Conferma la modifica','Le date delle attività saranno ricalcolate rispettando il calendario di produzione.')}<form><div class="dialog-body">${preview.changes.length?`<div class="change-list">${preview.changes.map(c=>`<div><strong>${esc(c.title)}</strong><p>${fmt(c.oldStart)} → <b>${fmt(c.start)}</b></p><small>Fine: ${fmt(c.oldEnd)} → ${fmt(c.end)}</small>${durationChanges(c)}</div>`).join('')}</div>`:'<p>Confermi questa operazione?</p>'}<p class="notice">L’anteprima è valida per 5 minuti. Le attività in corso e completate restano bloccate.</p></div>${dialogFooter('Conferma e salva')}</form>`,commit);
}
async function boot(){try{const s=await api('session');if(!s.user){renderAuth(s.needsSetup);return;}await reload();}catch(e){app.innerHTML=`<div class="loading">${esc(e.message)}<button class="button" id="retry">Riprova</button></div>`;$('#retry').onclick=boot;}}
function renderAuth(setup){app.innerHTML=`<div class="auth-layout"><section class="auth-brand"><div class="brand">${icon('machine')} ALOVEN<span>PRODUZIONE</span></div><div><p class="eyebrow">IL TEMPO, AL POSTO GIUSTO</p><h1>Ogni macchina.<br>Una sequenza chiara.</h1><p>Accoppiati tessili, materiali e calendari di lavoro<br>in un unico piano di produzione.</p><div class="auth-sequence"><span>Attrezzaggio</span><span>Produzione</span><span>Prossima attività</span></div></div><small>Pianificazione della produzione · Europe/Rome</small></section><section class="auth-form"><form id="auth"><p class="eyebrow">${setup?'PRIMO ACCESSO':'BENTORNATO'}</p><h2>${setup?'Configura il tuo reparto':'Accedi ad Aloven'}</h2><p>${setup?'Crea il primo account amministratore. Potrai poi aggiungere gli altri utenti.':'Accedi con le credenziali del tuo reparto.'}</p>${setup?'<label>Nome e cognome<input name="name" required maxlength="200" autocomplete="name"></label>':''}<label>Nome utente<input name="username" required maxlength="80" autocomplete="username"></label><label>Password<input name="password" type="password" required ${setup?'minlength="10"':''} maxlength="200" autocomplete="${setup?'new-password':'current-password'}"></label>${setup?'<small>Almeno 10 caratteri.</small>':''}<p id="auth-error" role="alert"></p><button class="button primary" type="submit">${setup?'Crea amministratore':'Accedi'} ${icon('arrow')}</button></form></section></div>`;
$('#auth').onsubmit=async e=>{e.preventDefault();const b=$('button',e.target);b.disabled=true;try{await api(setup?'setup':'login',Object.fromEntries(new FormData(e.target)));await reload();}catch(err){$('#auth-error').textContent=err.message;}finally{b.disabled=false;}};}
const nav=[['planning','Pianificazione','grid'],['shopfloor','Bordo macchina','machine'],['statistics','Statistiche','list'],['tasks','Attività','list'],['machines','Macchine','machine'],['types','Tipologie','tag'],['articles','Articoli','tag'],['setupRules','Attrezzaggi','clock'],['scrapReasons','Causali scarto','tag'],['machineStopReasons','Causali fermo','tag'],['calendar','Calendario','calendar'],['users','Utenti','users']];
function render(){if(!state)return;const oldScroll=$('.timeline-scroll'),scroll=oldScroll?{left:oldScroll.scrollLeft,top:oldScroll.scrollTop}:null;$('#time-tooltip')?.remove();if(view==='shopfloor'){app.innerHTML=shopfloorView(shopContext());bindShopfloor(shopContext());return;}const title=nav.find(x=>x[0]===view)?.[1];app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="/">${icon('machine')} ALOVEN<span>PRODUZIONE</span></a><p class="nav-caption">REPARTO PRODUTTIVO</p><nav>${nav.filter(x=>state.user.role==='admin'||!['users'].includes(x[0])).map(([id,label,ico])=>`<button data-nav="${id}" class="${view===id?'active':''}">${icon(ico)}${label}${id==='tasks'?`<span class="nav-count">${state.tasks.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="live-dot">Database connesso</div><div class="user"><span class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(state.user.name)}</strong><small>${state.user.role==='admin'?'Amministratore':'Operatore'}</small></div><button id="logout" class="icon-button" aria-label="Esci">${icon('logout')}</button></div></div></aside><main><header class="topbar"><span>Reparto <span class="slash">/</span> ${title}</span><div><span class="today">${new Intl.DateTimeFormat('it-IT',{dateStyle:'full',timeZone:'Europe/Rome'}).format(new Date())}</span><button class="button subtle" id="refresh">↻ Aggiorna</button></div></header><div class="workspace">${view==='planning'?planning():view==='statistics'?statisticsView(statisticsContext()):view==='calendar'?calendarView():['scrapReasons','machineStopReasons'].includes(view)?reasonCatalogView():['articles','setupRules'].includes(view)?advancedView():entityView()}</div></main></div>`;bindCommon();if(view==='planning'){bindPlanning();if(scroll){$('.timeline-scroll').scrollLeft=scroll.left;$('.timeline-scroll').scrollTop=scroll.top;}}else if(view==='statistics')bindStatistics(statisticsContext());else if(view==='calendar')bindCalendar();else if(['scrapReasons','machineStopReasons'].includes(view))bindReasonCatalog();else bindEntities();}
function heading(title,desc,button=''){return `<div class="page-heading"><div><p class="eyebrow">ALOVEN / PRODUZIONE</p><h1>${title}</h1><p>${desc}</p></div>${button}</div>`;}
function bindCommon(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='shopfloor'){location.href='/bordo-macchina';return;}view=b.dataset.nav;search='';render();window.scrollTo(0,0);});$('#logout').onclick=async()=>{await api('logout',{});state=null;await boot();};$('#refresh').onclick=()=>reload().catch(e=>toast(e.message,true));document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>editEntity(b.dataset.new));}
const materialFields=['component1Code','component1Description','component2Code','component2Description','productCode','productDescription'];
function matchesTask(t,query){const q=query.trim().toLocaleLowerCase('it');return !q||[t.title,...materialFields.map(f=>t[f])].some(v=>String(v||'').toLocaleLowerCase('it').includes(q));}
function materialFlow(t){return t.productCode?`<div class="material-flow"><div><span title="${esc(t.component1Description)}">${esc(t.component1Code)}</span><b>+</b><span title="${esc(t.component2Description)}">${esc(t.component2Code)}</span></div><p><span aria-hidden="true">↳</span><strong>${esc(t.productCode)}</strong></p><small>${esc(t.productDescription)}</small>${quantityCaption(t)}</div>`:'<div class="materials-missing">Componenti e articolo da completare</div>';}
function materialDetails(t){return `<section class="material-details"><h3>Componenti consumati → Articolo prodotto</h3>${[['component1','Componente 1'],['component2','Componente 2'],['product','Articolo prodotto']].map(([prefix,label])=>`<div class="${prefix==='product'?'product-row':''}"><span>${label}</span><strong>${esc(t[prefix+'Code']||'Da specificare')}</strong><p>${esc(t[prefix+'Description']||'Descrizione da specificare')}</p></div>`).join('')}</section>`;}
function materialForm(x){return `<section class="material-form"><h3>Componenti consumati</h3>${[1,2].map(i=>`<label>Componente ${i}<select aria-label="Componente ${i}" name="component${i}ArticleId" required>${articleOptions(x['component'+i+'ArticleId'],'component')}</select></label>`).join('')}<p class="notice">Codici e descrizioni provengono dall’anagrafica Articoli. Nessuna movimentazione di magazzino.</p></section>`;}
function taskCard(t){const ty=type(t.typeId);return `<article class="task-card" style="--task-color:${esc(ty?.color||'#2563eb')}" draggable="true" data-task="${t.id}"><div class="card-top"><span class="type-label">${esc(ty?.name)}</span><span class="grip">⠿</span></div><strong>${esc(t.title)}</strong>${materialFlow(t)}<p class="machine-label">${esc(machine(t.machineId)?.name)}</p><div class="card-bottom"><span>${icon('clock')} ${mins(t.runMinutes)}</span><span>Attr. ${mins(t.effectiveSetupMinutes??t.setupMinutes)}</span><button class="card-menu" data-detail="${t.id}" aria-label="Dettagli ${esc(t.title)}">⋯</button></div></article>`;}
function planning(){const visible=state.machines.filter(m=>!machineFilter||m.id===machineFilter);const ds=Array.from({length:planDays},(_,i)=>addDays(dateStart,i));const pending=state.tasks.filter(t=>t.status==='unplanned'&&(!machineFilter||t.machineId===machineFilter)&&matchesTask(t,search));const scoped=state.tasks.filter(t=>!machineFilter||t.machineId===machineFilter),scheduled=scoped.filter(t=>t.position!==null),load=periodLoad(state,visible,ds,effectiveShifts,showCompleted),warnings=planningWarnings(state);warningSignature=JSON.stringify([...warnings]);const affected=visible.filter(m=>scoped.some(t=>t.machineId===m.id&&warnings.has(t.id)));return `${heading('Piano di produzione','Pianifica gli accoppiati tessili, dai componenti all’articolo finito.',`<button class="button primary" data-new="task">${icon('plus')} Nuova attività</button>`)}<div class="metrics"><div><span>Macchine</span><strong data-metric="machines">${visible.length}<small>${machineFilter?'selezionata':'nel reparto'}</small></strong></div><div><span>Da assegnare</span><strong data-metric="pending">${scoped.filter(t=>t.status==='unplanned').length}<small>attività in attesa</small></strong></div><div><span>In sequenza</span><strong>${scheduled.filter(t=>t.status==='planned').length}<small>attività pianificate</small></strong></div><div><span>In lavorazione</span><strong class="green">${scoped.filter(t=>t.status==='in_progress').length}<small>attività in corso</small></strong></div></div><div class="load-summary"><strong>Carico nel periodo visualizzato</strong><span>${mins(load.occupied)} pianificati / ${mins(load.available)} disponibili · ${load.percent===null?'nessuna disponibilità':load.percent+'%'}</span><small>${machineFilter?esc(machine(machineFilter)?.name):'Tutte le macchine'} · ${showCompleted?'incluse le completate':'pianificate e in corso'}. I fermi aperti rendono il carico indicativo.</small></div>${affected.length?`<div class="planning-alert" role="status"><strong>Piano da verificare</strong>${affected.map(m=>`<p>${esc(m.name)}: ${esc(warnings.get(scoped.find(t=>t.machineId===m.id&&warnings.has(t.id)).id))}</p>`).join('')}</div>`:''}<div class="plan-toolbar"><div class="view-label">${icon('grid')} ${planDays===1?'Giornata / ore':'Gantt / periodo'}</div><div class="plan-view-switch" role="group" aria-label="Ampiezza della pianificazione"><button class="button ${planDays===5?'primary':'secondary'}" data-plan-days="5" aria-pressed="${planDays===5}">5 giorni</button><button class="button ${planDays===1?'primary':'secondary'}" data-plan-days="1" aria-pressed="${planDays===1}">Giorno</button></div><div class="date-controls"><button class="icon-button" id="prev-days" aria-label="${planDays===1?'Giorno precedente':'Cinque giorni precedenti'}">‹</button><input type="date" id="date-start" value="${dateStart}" aria-label="Primo giorno visualizzato"><button class="icon-button" id="next-days" aria-label="${planDays===1?'Giorno successivo':'Cinque giorni successivi'}">›</button><button class="button subtle" id="go-today">Oggi</button></div><select id="machine-filter" aria-label="Filtra macchina">${options(state.machines,machineFilter,'Tutte le macchine')}</select><label class="zoom-control">Zoom<select id="plan-zoom" aria-label="Zoom temporale">${[[.65,'Compatto'],[1,'Normale'],[1.5,'Dettaglio']].map(([v,label])=>`<option value="${v}" ${planZoom===v?'selected':''}>${label}</option>`).join('')}</select></label><label class="completed-toggle"><input id="show-completed" type="checkbox" ${showCompleted?'checked':''}>Mostra completate</label></div><div class="planner"><section class="backlog"><div class="backlog-title"><h2>Da assegnare</h2><span>${pending.length}</span></div><p>Trascina nella sequenza della macchina.</p><input class="search" id="queue-search" placeholder="Cerca attività o codice…" value="${esc(search)}" aria-label="Cerca attività o materiali non pianificati"><div class="backlog-cards" data-unplan>${pending.map(t=>taskCard(t)).join('')||'<div class="empty-small">Nessuna attività in attesa.<br>Crea una nuova attività per iniziare.</div>'}</div><div class="queue-hint">${icon('arrow')} Usa anche il menu ⋯ per pianificare senza trascinare.</div></section><div class="timeline-scroll">${temporalPlan(timeContext(),visible,ds,showCompleted)}</div></div><p class="notice plan-focus-note">${planDays===1?'Vista del giorno selezionato: include anche le lavorazioni iniziate prima che proseguono in questa giornata. ':'Clicca un giorno per concentrarti sulla sua pianificazione. '}Il filtro macchina mostra le attività in attesa della macchina scelta. L’inserimento tra le schede modifica la sequenza; “Aggiungi in coda macchina” accoda alla sequenza completa. Le date effettive dipendono dal calendario e sono mostrate nell’anteprima.</p><div class="plan-legend"><span><i class="legend-setup"></i> Attrezzaggio indivisibile</span><span><i class="legend-run"></i> Esecuzione distribuita nelle fasce</span><span>${icon('lock')} Attività in corso e completate bloccate</span><span>Le attività si accodano senza intervalli lavorativi, salvo attesa della fascia adatta all’attrezzaggio.</span></div>`;}
function effectiveShifts(d,id){return state.calendar.machineExceptions[id]?.[d]??state.calendar.exceptions[d]??state.calendar.weekly[new Date(d+'T12:00Z').getUTCDay()]??[];}
function bindPlanning(){
  $('#plan-zoom').onchange=e=>{planZoom=Number(e.target.value);localStorage.setItem('aloven-plan-zoom',String(planZoom));render();};
  bindTimeTips(timeContext());
  $('#show-completed').onchange=e=>{showCompleted=e.target.checked;render();};
  document.querySelectorAll('[data-machine-stop]').forEach(b=>b.onclick=()=>machineStopDialog(b.dataset.machineStop,b.dataset.stopAction));
  document.querySelectorAll('[data-maintenance]').forEach(b=>b.onclick=()=>{calendarScope=b.dataset.maintenance;exceptionDialog();});
  document.querySelectorAll('[data-plan-days]').forEach(b=>b.onclick=()=>{planDays=Number(b.dataset.planDays);localStorage.setItem('aloven-plan-view',planDays===1?'day':'five');render();});
  document.querySelectorAll('[data-focus-day]').forEach(b=>b.onclick=()=>{dateStart=b.dataset.focusDay;planDays=1;localStorage.setItem('aloven-plan-view','day');render();});
  document.querySelectorAll('[data-focus-machine]').forEach(b=>b.onclick=()=>{machineFilter=b.dataset.focusMachine;render();});
  $('#prev-days').onclick=()=>{dateStart=addDays(dateStart,-planDays);render();};$('#next-days').onclick=()=>{dateStart=addDays(dateStart,planDays);render();};$('#go-today').onclick=()=>{dateStart=localDate();render();};$('#date-start').onchange=e=>{if(e.target.value){dateStart=e.target.value;render();}};$('#machine-filter').onchange=e=>{machineFilter=e.target.value;render();};$('#queue-search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#queue-search').focus();$('#queue-search').setSelectionRange(pos,pos);};
  document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>taskDetails(b.dataset.detail));document.querySelectorAll('[data-sequence]').forEach(b=>b.onclick=()=>sequenceDialog(b.dataset.sequence));
  document.querySelectorAll('[data-append]').forEach(b=>b.onclick=()=>chooseActivity(b.dataset.append));
  document.querySelectorAll('[draggable=true]').forEach(c=>{c.ondragstart=e=>{dragging=true;dragTaskId=c.dataset.task;e.dataTransfer.setData('text/plain',c.dataset.task);e.dataTransfer.effectAllowed='move';c.classList.add('dragging');};c.ondragend=()=>{dragging=false;dragTaskId=null;clearInsertionHints();c.classList.remove('dragging');document.querySelectorAll('.drop-hover').forEach(x=>x.classList.remove('drop-hover'));};});
  document.querySelectorAll('[data-drop-machine]').forEach(cell=>{cell.ondragover=e=>{e.preventDefault();cell.classList.add('drop-hover');};cell.ondragleave=e=>{if(!cell.contains(e.relatedTarget))cell.classList.remove('drop-hover');};cell.ondrop=async e=>{e.preventDefault();dragging=false;cell.classList.remove('drop-hover');const id=e.dataTransfer.getData('text/plain'),t=state.tasks.find(x=>x.id===id);if(!t)return;if(t.machineId!==cell.dataset.dropMachine){toast('Questa attività è prevista su un’altra macchina. Modifica prima la macchina nell’attività.',true);return;}const beforeId=cell.dataset.insertionBefore??e.target.closest('[data-before]')?.dataset.before;dragTaskId=null;if(cell.dataset.insertionInvalid==='true'){clearInsertionHints();toast('Questa posizione è bloccata. Inserisci dopo le attività in corso o completate.',true);return;}clearInsertionHints();if(beforeId===id)return;try{await mutate({kind:'plan',id,beforeId},true);}catch(err){toast(err.message,true);}};});
  $('[data-unplan]').ondragover=e=>e.preventDefault();$('[data-unplan]').ondrop=async e=>{e.preventDefault();dragging=false;const id=e.dataTransfer.getData('text/plain');try{await mutate({kind:'plan',id,unplan:true});}catch(err){toast(err.message,true);}};
  bindInsertionHints(timeContext());
}
function chooseActivity(mid){const available=state.tasks.filter(t=>t.machineId===mid&&t.status==='unplanned');openDialog(`${dialogHeader('Aggiungi in coda',esc(machine(mid)?.name))}<form><div class="dialog-body">${available.length?`<label>Attività<select name="id">${available.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label>`:'<p>Nessuna attività da assegnare per questa macchina.</p>'}</div>${available.length?dialogFooter('Pianifica'):'<div class="dialog-footer"><button type="button" class="button" data-close-bottom>Chiudi</button></div>'}</form>`,f=>mutate({kind:'plan',id:f.get('id')}));}
function sequenceDialog(mid){const ts=state.tasks.filter(t=>t.machineId===mid&&t.position!==null).sort((a,b)=>a.position-b.position);openDialog(`${dialogHeader('Sequenza completa',esc(machine(mid)?.name))}<div class="dialog-body"><div class="sequence-list">${ts.map((t,i)=>`<div><span class="sequence-number">${i+1}</span><div><strong>${esc(t.title)}</strong><p>${fmt(t.start)} → ${fmt(t.end)}</p>${badge(t.status)}</div><button class="button subtle" data-detail="${t.id}">Dettagli</button></div>`).join('')||'<p>Nessuna attività pianificata.</p>'}</div></div>`);document.querySelectorAll('[data-detail]',modal).forEach(b=>b.onclick=()=>{modal.close();taskDetails(b.dataset.detail);});}
function taskDetails(id){const t=state.tasks.find(x=>x.id===id);const immutable=['in_progress','completed'].includes(t.status);const sequence=state.tasks.filter(x=>x.machineId===t.machineId&&x.position!==null&&x.id!==id).sort((a,b)=>a.position-b.position);openDialog(`${dialogHeader(esc(t.title),`${esc(machine(t.machineId)?.name)} · ${esc(type(t.typeId)?.name)}`)}<div class="dialog-body">${badge(t.status)}<div class="detail-grid"><div><span>Attrezzaggio</span><strong>${mins(t.effectiveSetupMinutes??t.setupMinutes)}</strong></div><div><span>Esecuzione</span><strong>${mins(t.runMinutes)}</strong></div><div><span>Inizio</span><strong>${fmt(t.start)}</strong></div><div><span>Fine</span><strong>${t.end?fmt(t.end):'Non pianificata'}</strong></div></div>${materialDetails(t)}${productionDetails(t)}${t.notes?`<p class="notes">${esc(t.notes)}</p>`:''}${t.segments.length?`<details><summary>Fasi e giornate (${t.segments.length})</summary><div class="segment-list">${t.segments.map(s=>`<p><span>${s.kind==='setup'?'Attrezzaggio':'Esecuzione'}</span> ${fmt(s.start)} → ${fmt(s.end)}</p>`).join('')}</div></details>`:''}${!immutable&&t.status!=='cancelled'?`<form id="plan-task"><label>Posizione nella sequenza<select name="beforeId"><option value="">Alla fine della sequenza</option>${sequence.map(x=>`<option value="${x.id}">Prima di: ${esc(x.title)}${['in_progress','completed'].includes(x.status)?' (bloccata)':''}</option>`).join('')}</select></label><button type="submit" class="button primary">${t.status==='unplanned'?'Pianifica':'Sposta'}</button></form>`:''}<div class="detail-actions">${!immutable?`<button class="button secondary" id="edit-task">Modifica attività</button>`:''}${t.status==='planned'?`<a class="button secondary" href="/bordo-macchina?machine=${t.machineId}">Apri bordo macchina</a><button class="button subtle" id="unplan-task">Torna da assegnare</button>`:''}${t.status==='in_progress'?`<a class="button primary" href="/bordo-macchina?machine=${t.machineId}">Rileva fasi al bordo macchina</a>`:''}${['planned','unplanned'].includes(t.status)?'<button class="button danger" data-state="cancelled">Annulla attività</button>':''}${t.status==='cancelled'?'<button class="button secondary" data-state="unplanned">Ripristina attività</button>':''}</div></div>`);$('#edit-task',modal)?.addEventListener('click',()=>{modal.close();editEntity('task',id);});$('#plan-task',modal)?.addEventListener('submit',async e=>{e.preventDefault();try{await mutate({kind:'plan',id,beforeId:new FormData(e.target).get('beforeId')});}catch(err){toast(err.message,true);}});$('#unplan-task',modal)?.addEventListener('click',()=>mutate({kind:'plan',id,unplan:true}).catch(e=>toast(e.message,true)));document.querySelectorAll('[data-state]',modal).forEach(b=>b.onclick=()=>mutate({kind:'status',id,status:b.dataset.state},true).catch(e=>toast(e.message,true)));}
function entityView(){const config={tasks:['Attività','Due componenti consumati, un articolo prodotto. Tempi e avanzamento di ogni lotto.','task'],machines:['Macchine','Risorse produttive e punto di partenza della pianificazione.','machine'],types:['Tipologie','Classifica le lavorazioni con nomi e colori riconoscibili.','type'],users:['Utenti','Gestisci gli accessi e i ruoli del reparto.','user']}[view];const admin=state.user.role==='admin';let rows='',head='';
if(view==='tasks'){head='<th>Attività</th><th>Macchina</th><th>Componenti consumati</th><th>Articolo prodotto</th><th>Tempi</th><th>Stato</th><th>Inizio / fine</th><th>Azioni</th>';rows=state.tasks.filter(t=>matchesTask(t,search)&&(!statusFilter||t.status===statusFilter)&&(!machineFilter||t.machineId===machineFilter)).map(t=>`<tr><td><strong>${esc(t.title)}</strong><small class="type-dot" style="--task-color:${esc(type(t.typeId)?.color)}">${esc(type(t.typeId)?.name)}</small></td><td>${esc(machine(t.machineId)?.name)}</td><td class="materials-column"><strong>${esc(t.component1Code||'Da specificare')}</strong><small>${esc(t.component1Description)}</small><strong>${esc(t.component2Code||'Da specificare')}</strong><small>${esc(t.component2Description)}</small></td><td class="materials-column product-column"><strong>${esc(t.productCode||'Da specificare')}</strong><small>${esc(t.productDescription)}</small></td><td><span>${mins(t.runMinutes)}</span><small>Attr. ${mins(t.effectiveSetupMinutes??t.setupMinutes)}</small></td><td>${badge(t.status)}</td><td>${t.start?`${fmt(t.start)}<small>${fmt(t.end)}</small>`:'—'}</td><td><div class="row-actions"><button data-detail="${t.id}" class="button subtle">Apri</button>${!['in_progress','completed'].includes(t.status)?`<button data-edit="task:${t.id}" class="button subtle">Modifica</button><button data-delete="task:${t.id}" class="button danger subtle">Elimina</button>`:''}</div></td></tr>`).join('');}
if(view==='machines'){head='<th>Macchina</th><th>Descrizione</th><th>Velocità</th><th>Inizio pianificazione</th><th>Attività</th><th>Azioni</th>';rows=state.machines.map(m=>`<tr><td><strong>${esc(m.name)}</strong></td><td>${esc(m.description)}</td><td>${m.speed} ${unitLabel(m.speedUnit)} / min</td><td>${fmt(m.anchor)}</td><td>${state.tasks.filter(t=>t.machineId===m.id).length}</td><td>${admin?rowActions('machine',m.id):'Solo lettura'}</td></tr>`).join('');}
if(view==='types'){head='<th>Tipologia</th><th>Colore</th><th>Attività</th><th>Azioni</th>';rows=state.types.map(t=>`<tr><td><strong>${esc(t.name)}</strong></td><td><span class="color-swatch" style="background:${esc(t.color)}"></span> ${esc(t.color)}</td><td>${state.tasks.filter(x=>x.typeId===t.id).length}</td><td>${admin?rowActions('type',t.id):'Solo lettura'}</td></tr>`).join('');}
if(view==='users'){head='<th>Nome</th><th>Nome utente</th><th>Ruolo</th><th>Azioni</th>';rows=state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong>${u.id===state.user.id?'<small>Il tuo account</small>':''}</td><td>${esc(u.username)}</td><td><span class="badge">${u.role==='admin'?'Amministratore':'Operatore'}</span></td><td>${rowActions('user',u.id)}</td></tr>`).join('');}
return `${heading(config[0],config[1],admin||view==='tasks'?`<button class="button primary" data-new="${config[2]}">${icon('plus')} ${view==='tasks'?'Nuova attività':view==='machines'?'Nuova macchina':view==='types'?'Nuova tipologia':'Nuovo utente'}</button>`:'')}${view==='tasks'?`<div class="table-toolbar"><input id="task-search" placeholder="Cerca attività o codice…" value="${esc(search)}" aria-label="Cerca attività"><select id="status-filter">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${statusFilter===k?'selected':''}>${v}</option>`).join('')}<option value="" ${!statusFilter?'selected':''}>Tutti gli stati</option></select><select id="machine-filter">${options(state.machines,machineFilter,'Tutte le macchine')}</select></div>`:''}<div class="table-wrap"><table><thead><tr>${head}</tr></thead><tbody>${rows||`<tr><td colspan="8" class="empty-small">Nessun elemento da mostrare.</td></tr>`}</tbody></table></div>${view==='users'?'<p class="notice">Gli operatori gestiscono attività e pianificazione. Gli amministratori gestiscono anche macchine, tipologie, calendario e utenti.</p>':''}`;}
function rowActions(kind,id){return `<div class="row-actions"><button class="button subtle" data-edit="${kind}:${id}">Modifica</button><button class="button danger subtle" data-delete="${kind}:${id}">Elimina</button></div>`;}
function bindEntities(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editEntity(...b.dataset.edit.split(':')));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteEntity(...b.dataset.delete.split(':')));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>taskDetails(b.dataset.detail));$('#status-filter')?.addEventListener('change',e=>{statusFilter=e.target.value;render();});$('#machine-filter')?.addEventListener('change',e=>{machineFilter=e.target.value;render();});$('#task-search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#task-search').focus();$('#task-search').setSelectionRange(pos,pos);});}
function editEntity(kind,id){if(['article','setupRule'].includes(kind)){editAdvanced(kind,id);return;}const plural={task:'tasks',machine:'machines',type:'types',user:'users'};const x=state[plural[kind]].find(x=>x.id===id)||{};let fields='';const title={task:'attività',machine:'macchina',type:'tipologia',user:'utente'}[kind];
if(kind==='task'){if(!state.machines.length||!state.types.length){toast('Crea prima almeno una macchina e una tipologia.',true);return;}fields=`<section class="product-identity"><label>Prodotto da realizzare<select aria-label="Prodotto da realizzare" name="productArticleId" required>${articleOptions(x.productArticleId,'product')}</select></label><input type="hidden" name="title" value="${esc(x.title)}">${x.title?`<p class="notice">Denominazione esistente: ${esc(x.title)}</p>`:''}<p class="notice">Il nome della nuova lavorazione deriva dal prodotto selezionato.</p></section><div class="form-grid"><label>Tipologia<select name="typeId">${options(state.types,x.typeId)}</select></label><label>Macchina obbligatoria<select aria-label="Macchina" name="machineId">${options(state.machines,x.machineId)}</select></label><label>Attrezzaggio (minuti)<input name="setupMinutes" type="number" min="0" max="525600" step="1" required value="${x.setupMinutes??30}"></label><label>Esecuzione (minuti)<input name="runMinutes" type="number" min="1" max="525600" step="1" required value="${x.runMinutes??60}"></label></div>${materialForm(x)}${productionForm(x)}<label>Note<textarea name="notes" aria-label="Note" maxlength="2000" rows="3">${esc(x.notes)}</textarea></label><p class="notice">L’attrezzaggio viene eseguito una sola volta e deve rientrare interamente in una fascia lavorativa.</p>`;}
if(kind==='machine')fields=`<label>Nome macchina<input name="name" required maxlength="200" value="${esc(x.name)}"></label><label>Descrizione<input name="description" maxlength="500" value="${esc(x.description)}"></label><label>Inizio della pianificazione<input type="datetime-local" name="anchor" required value="${x.anchor||localDate()+'T08:00'}"></label><div class="form-grid"><label>Velocità macchina<input type="number" name="speed" required min="0.001" step="any" value="${x.speed??10}"></label><label>Unità della velocità<select name="speedUnit">${unitOptions(x.speedUnit||'m')}</select></label></div><p class="notice">La velocità è espressa in unità al minuto e viene usata per le attività con calcolo automatico.</p><p class="notice">Le attività si susseguono a partire da questa data, rispettando i giorni e le fasce lavorative.</p>`;
if(kind==='type')fields=`<label>Nome tipologia<input name="name" required maxlength="200" value="${esc(x.name)}"></label><label>Colore<input type="color" name="color" value="${x.color||'#2563eb'}"></label>`;
if(kind==='user')fields=`<label>Nome e cognome<input name="name" required maxlength="200" value="${esc(x.name)}"></label><label>Nome utente<input name="username" required maxlength="80" autocomplete="off" value="${esc(x.username)}"></label><label>Ruolo<select name="role"><option value="operator" ${x.role==='operator'?'selected':''}>Operatore</option><option value="admin" ${x.role==='admin'?'selected':''}>Amministratore</option></select></label><label>${id?'Nuova password (lascia vuoto per mantenerla)':'Password'}<input name="password" type="password" minlength="10" maxlength="200" ${id?'':'required'} autocomplete="new-password"></label><p class="notice">Almeno 10 caratteri. Cambiare la password disconnette le sessioni dell’utente.</p>`;
openDialog(`${dialogHeader(`${id?'Modifica':'Nuova'} ${title}`)}<form><div class="dialog-body">${fields}</div>${dialogFooter()}</form>`,async f=>{const values=Object.fromEntries(f);if(kind==='machine')values.speed=Number(values.speed);if(kind==='task'){values.setupMinutes=Number(values.setupMinutes);values.runMinutes=Number(values.runMinutes);values.quantity=values.quantity?Number(values.quantity):null;}if(kind==='user'){await api('users',{id,...values});modal.close();await boot();toast('Utente salvato.');}else await mutate({kind,id,values});});if(kind==='task')bindProductionForm();}
function deleteEntity(kind,id){openDialog(`${dialogHeader('Elimina elemento')}<form><div class="dialog-body"><p>Confermi l’eliminazione? Gli elementi utilizzati da altre entità e le attività bloccate sono protetti.</p></div>${dialogFooter('Elimina')}</form>`,async()=>{if(kind==='user'){await api('users',{id,remove:true});modal.close();await reload();toast('Utente eliminato.');}else await mutate({kind,id,remove:true});});}
function shiftInputs(shifts,prefix){return `<div class="shift-inputs">${[0,1].map(i=>`<div><input type="time" name="${prefix}-${i}-start" value="${shifts[i]?.[0]||''}" aria-label="Inizio fascia ${i+1}"><span>—</span><input type="time" name="${prefix}-${i}-end" value="${shifts[i]?.[1]||''}" aria-label="Fine fascia ${i+1}"></div>`).join('')}</div>`;}
function readShifts(f,prefix,working=true){if(!working)return [];const shifts=[];for(let i=0;i<2;i++){const start=f.get(`${prefix}-${i}-start`),end=f.get(`${prefix}-${i}-end`);if(!start&&!end)continue;if(!start||!end||start>=end)throw new Error('Completa ogni fascia con un inizio precedente alla fine.');shifts.push([start,end]);}if(!shifts.length)throw new Error('Indica almeno una fascia per un giorno lavorativo.');if(shifts.length===2&&shifts[1][0]<shifts[0][1])throw new Error('Le fasce non devono sovrapporsi e devono essere in ordine.');return shifts;}
function calendarView(){const admin=state.user.role==='admin';const first=calendarMonth+'-01',dow=new Date(first+'T12:00Z').getUTCDay(),gridStart=addDays(first,-((dow+6)%7));const exceptionMap=calendarScope==='global'?state.calendar.exceptions:(state.calendar.machineExceptions[calendarScope]||{});const cells=Array.from({length:42},(_,i)=>{const d=addDays(gridStart,i),outside=d.slice(0,7)!==calendarMonth;const shifts=calendarScope==='global'?(state.calendar.exceptions[d]??state.calendar.weekly[new Date(d+'T12:00Z').getUTCDay()]):effectiveShifts(d,calendarScope);return `<button class="calendar-day ${outside?'outside':''} ${!shifts?.length?'off':''} ${Object.hasOwn(exceptionMap,d)?'exception':''} ${d===localDate()?'today-cell':''}" data-day="${d}" ${!admin?'disabled':''}><span>${Number(d.slice(8))}</span><small>${shifts?.length?shifts.map(s=>s.join('–')).join('<br>'):'Non lavorativo'}</small>${Object.hasOwn(exceptionMap,d)?'<em>Eccezione</em>':''}</button>`;});return `${heading('Calendario di produzione','Una settimana standard, con eccezioni per data e per macchina.',admin?'<button class="button primary" id="bulk-exception">'+icon('plus')+' Imposta periodo</button>':'')}<div class="calendar-layout"><section class="panel weekly"><div class="panel-heading"><h2>Settimana standard</h2><small>Comune a tutte le macchine</small></div><form id="weekly-form"><fieldset ${!admin?'disabled':''}><div class="weekly-labels"><span>Giorno lavorativo</span><span>Fascia 1 / Fascia 2</span></div>${[1,2,3,4,5,6,0].map(day=>`<div class="weekly-row"><label class="check-label"><input type="checkbox" name="work-${day}" ${state.calendar.weekly[day]?.length?'checked':''}>${days[day]}</label>${shiftInputs(state.calendar.weekly[day]||[],`day-${day}`)}</div>`).join('')}<div class="weekly-actions"><button type="button" class="button secondary" id="bulk-week">Applica orari a più giorni</button><button class="button primary" type="submit">Salva settimana</button></div></fieldset></form><p class="notice">Le fasce vuote non sono utilizzate. Le eccezioni per data prevalgono sulla settimana standard.</p></section><section class="panel month-panel"><div class="month-toolbar"><button class="icon-button" id="prev-month" aria-label="Mese precedente">‹</button><h2>${new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(first+'T12:00Z'))}</h2><button class="icon-button" id="next-month" aria-label="Mese successivo">›</button><select id="calendar-scope" aria-label="Calendario macchina"><option value="global">Calendario generale</option>${options(state.machines,calendarScope)}</select></div><div class="month-grid">${[1,2,3,4,5,6,0].map(d=>`<div class="weekday">${days[d].slice(0,3)}</div>`).join('')}${cells.join('')}</div><div class="calendar-legend"><span>● Lavorativo</span><span>○ Non lavorativo</span><span class="amber">● Eccezione</span></div></section></div><section class="panel exceptions-panel"><div class="panel-heading"><h2>Eccezioni ${calendarScope==='global'?'generali':esc(machine(calendarScope)?.name)}</h2><small>Le eccezioni della macchina prevalgono su quelle generali.</small></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Disponibilità</th><th>Azioni</th></tr></thead><tbody>${Object.entries(exceptionMap).sort(([a],[b])=>a.localeCompare(b)).map(([date,shifts])=>`<tr><td>${new Intl.DateTimeFormat('it-IT',{dateStyle:'full',timeZone:'UTC'}).format(new Date(date+'T12:00Z'))}</td><td>${shifts.length?shifts.map(s=>s.join('–')).join(' / '):'<span class="badge cancelled">Non lavorativo</span>'}</td><td>${admin?`<div class="row-actions"><button data-ex-edit="${date}" class="button subtle">Modifica</button><button data-ex-remove="${date}" class="button danger subtle">Ripristina standard</button></div>`:'Solo lettura'}</td></tr>`).join('')||'<tr><td colspan="3" class="empty-small">Nessuna eccezione. Si applica il calendario generale.</td></tr>'}</tbody></table></div></section>`;}
function bindCalendar(){const changeMonth=n=>{const d=new Date(calendarMonth+'-01T12:00Z');d.setUTCMonth(d.getUTCMonth()+n);calendarMonth=d.toISOString().slice(0,7);render();};$('#prev-month').onclick=()=>changeMonth(-1);$('#next-month').onclick=()=>changeMonth(1);$('#calendar-scope').value=calendarScope;$('#calendar-scope').onchange=e=>{calendarScope=e.target.value;render();};$('#weekly-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),cal=structuredClone(state.calendar);try{for(let i=0;i<7;i++)cal.weekly[i]=readShifts(f,`day-${i}`,f.has(`work-${i}`));await mutate({kind:'calendar',values:cal},true);}catch(err){toast(err.message,true);}};$('#bulk-week')?.addEventListener('click',bulkWeek);$('#bulk-exception')?.addEventListener('click',()=>exceptionDialog());document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>exceptionDialog(b.dataset.day));document.querySelectorAll('[data-ex-edit]').forEach(b=>b.onclick=()=>exceptionDialog(b.dataset.exEdit));document.querySelectorAll('[data-ex-remove]').forEach(b=>b.onclick=()=>{const cal=structuredClone(state.calendar);const map=calendarScope==='global'?cal.exceptions:cal.machineExceptions[calendarScope];delete map[b.dataset.exRemove];mutate({kind:'calendar',values:cal},true).catch(e=>toast(e.message,true));});}
function dayChecks(prefix){return `<div class="day-checks">${[1,2,3,4,5,6,0].map(d=>`<label class="check-label"><input type="checkbox" name="${prefix}-${d}" ${d!==0&&d!==6?'checked':''}>${days[d].slice(0,3)}</label>`).join('')}</div>`;}
function bulkWeek(){openDialog(`${dialogHeader('Applica orari a più giorni','Seleziona i giorni della settimana da aggiornare.')}<form><div class="dialog-body">${dayChecks('select')}<label class="check-label"><input type="checkbox" name="working" checked>Giorni lavorativi</label>${shiftInputs([['08:00','12:00'],['13:00','17:00']],'bulk')}</div>${dialogFooter('Applica')}</form>`,async f=>{const cal=structuredClone(state.calendar),shifts=readShifts(f,'bulk',f.has('working'));let n=0;for(let i=0;i<7;i++)if(f.has(`select-${i}`)){cal.weekly[i]=shifts;n++;}if(!n)throw new Error('Seleziona almeno un giorno.');await mutate({kind:'calendar',values:cal},true);});}
function exceptionDialog(date){const shifts=date?(calendarScope==='global'?(state.calendar.exceptions[date]??state.calendar.weekly[new Date(date+'T12:00Z').getUTCDay()]):effectiveShifts(date,calendarScope)):[['08:00','12:00'],['13:00','17:00']];openDialog(`${dialogHeader(date?'Eccezione del giorno':'Imposta un periodo','Modifica giorni lavorativi e fasce per una data o un intervallo.')}<form><div class="dialog-body"><label>Ambito<select name="scope"><option value="global">Tutte le macchine</option>${options(state.machines,calendarScope)}</select></label><div class="form-grid"><label>Dal<input type="date" name="from" required value="${date||calendarMonth+'-01'}"></label><label>Al<input type="date" name="to" required value="${date||calendarMonth+'-01'}"></label></div>${date?'':dayChecks('select')}<label class="check-label"><input type="checkbox" name="working" ${shifts.length?'checked':''}>Giorno lavorativo</label>${shiftInputs(shifts,'ex')}<p class="notice">Per una chiusura, deseleziona “Giorno lavorativo”. Puoi impostare fino a 366 giorni per volta.</p></div>${dialogFooter('Salva eccezioni')}</form>`,async f=>{const from=f.get('from'),to=f.get('to');if(from>to)throw new Error('La data finale deve seguire quella iniziale.');const count=(new Date(to+'T12:00Z')-new Date(from+'T12:00Z'))/86400000+1;if(count>366)throw new Error('Seleziona un periodo massimo di 366 giorni.');const cal=structuredClone(state.calendar),scope=f.get('scope'),map=scope==='global'?cal.exceptions:(cal.machineExceptions[scope]??={}),ss=readShifts(f,'ex',f.has('working'));let n=0;for(let i=0;i<count;i++){const d=addDays(from,i);if(date||f.has(`select-${new Date(d+'T12:00Z').getUTCDay()}`)){map[d]=ss;n++;}}if(!n)throw new Error('Nessuna data corrisponde ai giorni selezionati.');await mutate({kind:'calendar',values:cal},true);});$('select[name=scope]',modal).value=calendarScope;}
setInterval(async()=>{if(!state||modal.open||dragging)return;try{const latest=await api('state');if(latest.revision!==state.revision){state=latest;render();toast('Piano aggiornato con le modifiche del reparto.');}else if(view==='planning'&&JSON.stringify([...planningWarnings(state)])!==warningSignature)render();}catch{}},15000);
boot();

function unitLabel(unit){return {m:'m lineari',m2:'m²',kg:'kg'}[unit]||unit;}
function quantityCaption(t){const article=state.articles?.find(a=>a.id===t.productArticleId);return t.quantity?`<small class="quantity-caption">${t.quantity} ${unitLabel(article?.unit||'m')} · ${t.calculationMode==='automatic'?'Tempo automatico':'Tempo manuale'}</small>`:'';}
function durationChanges(c){return `${c.oldRunMinutes!==undefined&&c.oldRunMinutes!==c.runMinutes?`<p>Esecuzione: ${mins(c.oldRunMinutes)} → <b>${mins(c.runMinutes)}</b></p>`:''}${c.oldSetupMinutes!==undefined&&c.oldSetupMinutes!==c.setupMinutes?`<p>Attrezzaggio: ${mins(c.oldSetupMinutes)} → <b>${mins(c.setupMinutes)}</b></p>`:''}`;}
function unitOptions(unit){return ['m','m2','kg'].map(v=>`<option value="${v}" ${unit===v?'selected':''}>${unitLabel(v)} / min</option>`).join('');}
function articleOptions(id,kind){return `<option value="">Seleziona un articolo…</option>${(state.articles||[]).filter(a=>a.kind===kind||a.kind==='both'||a.id===id).map(a=>`<option value="${esc(a.id)}" ${a.id===id?'selected':''}>${esc(a.code)} · ${esc(a.description)} (${unitLabel(a.unit)})</option>`).join('')}`;}
function productionForm(t){return `<section class="production-form"><h3>Quantità e tempo di esecuzione</h3><div class="form-grid"><label>Quantità da produrre<input name="quantity" type="number" min="0.001" max="1000000000" step="any" value="${t.quantity??''}" placeholder="Es. 1200"></label><label>Calcolo del tempo<select aria-label="Calcolo del tempo" name="calculationMode"><option value="manual" ${t.calculationMode!=='automatic'?'selected':''}>Tempo manuale</option><option value="automatic" ${t.calculationMode==='automatic'?'selected':''}>Quantità ÷ velocità macchina</option></select></label></div><p class="calculation-summary" id="calculation-summary" aria-live="polite"></p><p class="notice">Il tempo automatico è arrotondato al minuto superiore. Unità dell’articolo e della velocità devono coincidere. L’attrezzaggio è aggiunto separatamente.</p></section>`;}
function bindProductionForm(){const f=$('form',modal);const initialProduct=f.elements.productArticleId.value;const initialTitle=f.elements.title.value;f.elements.productArticleId.addEventListener('change',()=>{const a=state.articles.find(a=>a.id===f.elements.productArticleId.value);f.elements.title.value=f.elements.productArticleId.value===initialProduct&&initialTitle?initialTitle:(a?.description||'');});const update=()=>{const mode=f.elements.calculationMode.value,qty=f.elements.quantity,run=f.elements.runMinutes,m=machine(f.elements.machineId.value),article=state.articles.find(a=>a.id===f.elements.productArticleId.value);qty.required=mode==='automatic';run.readOnly=mode==='automatic';const summary=$('#calculation-summary',modal);if(mode==='manual'){summary.textContent='Tempo di esecuzione inserito manualmente.';return;}if(!article){summary.textContent='Seleziona l’articolo prodotto per verificare l’unità di misura.';return;}if(article.unit!==m.speedUnit){summary.textContent=`Unità incompatibili: articolo in ${unitLabel(article.unit)}, macchina in ${unitLabel(m.speedUnit)} / min.`;return;}const q=Number(qty.value);if(q>0&&m.speed>0){const minutes=Math.ceil(q/m.speed);run.value=minutes;summary.textContent=`${q} ${unitLabel(article.unit)} ÷ ${m.speed} ${unitLabel(m.speedUnit)} / min = ${mins(minutes)} di esecuzione.`;}else summary.textContent='Inserisci la quantità da produrre.';};for(const name of ['quantity','calculationMode','machineId','productArticleId'])f.elements[name].addEventListener('input',update);update();}
function productionDetails(t){const a=state.articles?.find(x=>x.id===t.productArticleId);return `<div class="detail-grid"><div><span>Quantità da produrre</span><strong>${t.quantity!==null&&t.quantity!==undefined?`${t.quantity} ${unitLabel(a?.unit||'m')}`:'Non indicata'}</strong></div><div><span>Calcolo esecuzione</span><strong>${t.calculationMode==='automatic'?'Quantità ÷ velocità':'Tempo manuale'}</strong></div><div><span>Attrezzaggio base</span><strong>${mins(t.setupMinutes)}</strong></div><div><span>Attrezzaggio applicato</span><strong>${mins(t.effectiveSetupMinutes??t.setupMinutes)}</strong></div></div>`;}
function advancedView(){const articles=view==='articles',admin=state.user.role==='admin',items=articles?state.articles:state.setupRules;const title=articles?'Anagrafica articoli':'Regole di attrezzaggio',kind=articles?'article':'setupRule';const rows=(items||[]).filter(x=>!articles||!search||[x.code,x.description].some(v=>v.toLowerCase().includes(search.toLowerCase()))).map(x=>articles?`<tr><td><strong class="article-code">${esc(x.code)}</strong></td><td class="article-description">${esc(x.description)}</td><td>${unitLabel(x.unit)}</td><td>${{component:'Componente',product:'Articolo prodotto',both:'Componente e prodotto'}[x.kind]}</td><td>${admin?rowActions(kind,x.id):'Solo lettura'}</td></tr>`:`<tr><td>${esc(machine(x.machineId)?.name)}</td><td>${esc(type(x.fromTypeId)?.name)}</td><td>${esc(type(x.toTypeId)?.name)}</td><td><strong>${mins(x.minutes)}</strong></td><td>${admin?rowActions(kind,x.id):'Solo lettura'}</td></tr>`).join('');return `${heading(title,articles?'Codici, descrizioni e unità di misura condivisi tra le attività.':'Definisci il tempo di preparazione passando da una lavorazione alla successiva.',admin?`<button class="button primary" data-new="${kind}">${icon('plus')} ${articles?'Nuovo articolo':'Nuova regola'}</button>`:'')}${articles?`<div class="table-toolbar"><input id="task-search" placeholder="Cerca codice o descrizione…" aria-label="Cerca articolo" value="${esc(search)}"></div>`:''}<div class="table-wrap"><table><thead><tr>${articles?'<th>Codice</th><th>Descrizione</th><th>Unità</th><th>Uso</th><th>Azioni</th>':'<th>Macchina</th><th>Lavorazione precedente</th><th>Lavorazione successiva</th><th>Attrezzaggio</th><th>Azioni</th>'}</tr></thead><tbody>${rows||'<tr><td colspan="5" class="empty-small">Nessun elemento. Aggiungine uno per iniziare.</td></tr>'}</tbody></table></div><p class="notice">${articles?'Gli articoli utilizzati non possono essere eliminati. Codici e descrizioni delle attività non bloccate seguono l’anagrafica; le attività in corso e completate conservano i dati storici.':'La regola sostituisce il tempo base dell’attività quando le due tipologie si susseguono sulla macchina scelta. La prima attività e i passaggi senza regola usano il tempo base. Le attività bloccate mantengono l’attrezzaggio già applicato.'}</p>`;}
function editAdvanced(kind,id){const article=kind==='article',items=article?state.articles:state.setupRules,x=items.find(t=>t.id===id)||{};if(!article&&(!state.types.length||!state.machines.length)){toast('Crea prima una macchina e una tipologia.',true);return;}const fields=article?`<label>Codice articolo<input name="code" required maxlength="80" value="${esc(x.code)}"></label><label>Descrizione articolo<input name="description" required maxlength="200" value="${esc(x.description)}"></label><div class="form-grid"><label>Unità di misura<select name="unit">${['m','m2','kg'].map(v=>`<option value="${v}" ${x.unit===v?'selected':''}>${unitLabel(v)}</option>`).join('')}</select></label><label>Utilizzo<select aria-label="Utilizzo" name="kind"><option value="component" ${x.kind==='component'?'selected':''}>Componente</option><option value="product" ${x.kind==='product'?'selected':''}>Articolo prodotto</option><option value="both" ${x.kind==='both'?'selected':''}>Componente e prodotto</option></select></label></div>`:`<label>Macchina<select aria-label="Macchina" name="machineId">${options(state.machines,x.machineId)}</select></label><label>Lavorazione precedente<select aria-label="Lavorazione precedente" name="fromTypeId">${options(state.types,x.fromTypeId)}</select></label><label>Lavorazione successiva<select aria-label="Lavorazione successiva" name="toTypeId">${options(state.types,x.toTypeId)}</select></label><label>Attrezzaggio del passaggio (minuti)<input name="minutes" type="number" required min="0" max="525600" step="1" value="${x.minutes??15}"></label><p class="notice">La modifica ricalcola la sequenza della macchina. Controlla l’anteprima prima di confermare.</p>`;openDialog(`${dialogHeader(`${id?'Modifica':article?'Nuovo':'Nuova'} ${article?'articolo':'regola'}`)}<form><div class="dialog-body">${fields}</div>${dialogFooter()}</form>`,async f=>{const values=Object.fromEntries(f);if(!article)values.minutes=Number(values.minutes);await mutate({kind,id,values},true);});}

function shopContext(){return {state,esc,icon,localDate,addDays,fmt,mins,unitLabel,machine,type,materialDetails,openDialog,dialogHeader,dialogFooter,api,reload,toast,render};}

function reasonCatalogView(){const scrap=view==='scrapReasons',admin=state.user.role==='admin',items=state[view]||[];return `${heading(scrap?'Causali scarto':'Causali fermo macchina','Le causali attive sono selezionabili dagli operatori. Le dichiarazioni conservano la descrizione originale.',admin?'<button class="button primary" id="new-cause">Nuova causale</button>':'')}<div class="table-wrap"><table><thead><tr><th>Codice</th><th>Descrizione italiana</th><th>Descrizione inglese</th><th>Stato</th><th>Azioni</th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${esc(x.code)}</strong></td><td>${esc(x.description)}</td><td>${esc(x.descriptionEn||x.description)}</td><td>${x.active?'Attiva':'Disattivata'}</td><td>${admin?`<button class="button subtle" data-edit-cause="${esc(x.id)}">Modifica</button><button class="button subtle" data-toggle-cause="${esc(x.id)}">${x.active?'Disattiva':'Attiva'}</button><button class="button danger" data-remove-cause="${esc(x.id)}">Elimina</button>`:'Solo lettura'}</td></tr>`).join('')||'<tr><td colspan="5">Nessuna causale disponibile.</td></tr>'}</tbody></table></div><p class="notice">Una causale già utilizzata può essere disattivata. Rimarrà nello storico ma non verrà proposta per nuove registrazioni.</p>`;}
function reasonEndpoint(){return view==='scrapReasons'?'scrap-reasons':'machine-stop-reasons';}
function bindReasonCatalog(){const items=state[view]||[];$('#new-cause')?.addEventListener('click',()=>editReason());document.querySelectorAll('[data-edit-cause]').forEach(b=>b.onclick=()=>editReason(b.dataset.editCause));document.querySelectorAll('[data-toggle-cause]').forEach(b=>b.onclick=async()=>{const x=items.find(x=>x.id===b.dataset.toggleCause);b.disabled=true;try{await api(reasonEndpoint(),{revision:state.revision,...x,active:!x.active});await reload();}catch(e){toast(e.message,true);b.disabled=false;}});document.querySelectorAll('[data-remove-cause]').forEach(b=>b.onclick=()=>{const x=items.find(x=>x.id===b.dataset.removeCause),endpoint=reasonEndpoint();openDialog(`${dialogHeader('Elimina causale')}<form><div class="dialog-body"><p>${esc(x.code)} · ${esc(x.description)}</p></div>${dialogFooter('Elimina')}</form>`,async()=>{await api(endpoint,{revision:state.revision,id:x.id,remove:true});modal.close();await reload();});});}
function editReason(id){const x=(state[view]||[]).find(x=>x.id===id)||{},endpoint=reasonEndpoint();openDialog(`${dialogHeader(id?'Modifica causale':'Nuova causale')}<form><div class="dialog-body"><label>Codice<input name="code" maxlength="40" required value="${esc(x.code)}"></label><label>Descrizione italiana<input name="description" maxlength="200" required value="${esc(x.description)}"></label><label>Descrizione inglese<input name="descriptionEn" maxlength="200" value="${esc(x.descriptionEn)}"></label><label>Stato<select name="active"><option value="true" ${x.active!==false?'selected':''}>Attiva</option><option value="false" ${x.active===false?'selected':''}>Disattivata</option></select></label></div>${dialogFooter()}</form>`,async f=>{await api(endpoint,{revision:state.revision,id,...Object.fromEntries(f),active:f.get('active')==='true'});modal.close();await reload();toast('Causale salvata.');});}

function timeContext(){return {state,esc,fmt,mins,machine,type,labels,effectiveShifts,zoom:planZoom,planWarnings:planningWarnings(state),dragTaskId:()=>dragTaskId};}
function machineStopDialog(id,action){const stop=(state.machineStops||[]).find(x=>x.machineId===id&&!x.endedAt);openDialog(`${dialogHeader(action==='stop'?'Ferma macchina':'Riattiva macchina',esc(machine(id)?.name))}<form><div class="dialog-body">${action==='stop'?`<label>Motivo del fermo<select name="reasonId" required><option value="">Seleziona una causale</option>${(state.machineStopReasons||[]).filter(x=>x.active).map(x=>`<option value="${esc(x.id)}">${esc(x.code)} · ${esc(x.description)}</option>`).join('')}</select></label><p class="notice">La lavorazione attiva sarà sospesa. Non potranno iniziare nuove fasi. La durata del fermo resta aperta: le date del piano dovranno essere verificate alla ripresa. Termina prima un eventuale attrezzaggio in corso.</p>`:`<p>Fermo: ${esc(stop?.reason)}</p><p class="notice">La macchina torna disponibile. La lavorazione sospesa richiede una ripresa esplicita al bordo macchina. Verifica il piano prima di procedere.</p>`}<h3>Ultimi fermi</h3>${(state.machineStops||[]).filter(x=>x.machineId===id).slice(0,5).map(x=>`<p>${esc(x.reason)} · ${esc(x.startedAt)} → ${esc(x.endedAt||'In corso')}</p>`).join('')||'<p>Nessun fermo registrato.</p>'}</div>${dialogFooter('Conferma')}</form>`,async f=>{await api('machine-stop',{revision:state.revision,machineId:id,action,reasonId:f.get('reasonId')||null});modal.close();await reload();toast('Stato macchina aggiornato.');});}

function statisticsContext(){return {state,esc,localDate,unitLabel,heading,api,render,toast,isActive:()=>view==='statistics'};}
